import { Box3, Vector3 } from './webgi-re-exports'
import { IjewelViewer } from './ijewel-viewer'

const runtimeConfig = (window as any).WEBGI_VIEWER_CONFIG || {}
const MODEL_PATH = runtimeConfig.modelPath || './assets/lrs-01.glb'
const ENV_PATH = runtimeConfig.environmentPath || './assets/env_metal_001.hdr'
const AUTO_ROTATE = runtimeConfig.autoRotate !== false
const ROTATION_SPEED = Number.isFinite(runtimeConfig.rotationSpeed) ? runtimeConfig.rotationSpeed : 0.4

let viewer: any = null
let ijewelViewer: IjewelViewer | null = null
let ringModel: any = null
let modelLoaded = false
let rotationY = 0
const MAX_TILT = Math.PI / 2.2

const ringFitCenter = { x: 0, y: 0, z: 0 }

const loaderEl = document.getElementById('loader') as HTMLElement

function computeRingBounds(root: any): any {
    const box = new Box3()
    if (!root) return box
    if (typeof root.updateWorldMatrix === 'function') {
        box.setFromObject(root)
    } else if (typeof root.traverse === 'function') {
        root.traverse((child: any) => {
            if (!child.geometry) return
            const geom = child.geometry
            if (!geom.boundingBox && typeof geom.computeBoundingBox === 'function') geom.computeBoundingBox()
            if (geom.boundingBox) {
                box.min.min(geom.boundingBox.min)
                box.max.max(geom.boundingBox.max)
            }
        })
    } else if (root.geometry?.boundingBox) {
        box.copy(root.geometry.boundingBox)
    }
    return box
}

function frameRing() {
    if (!viewer || !ringModel) return
    const cam = viewer.scene.activeCamera
    if (!cam) return
    ringModel.position.set(-ringFitCenter.x, -ringFitCenter.y, -ringFitCenter.z)
    ringModel.rotation.order = 'YXZ'
    ringModel.rotation.x = 0
    ringModel.rotation.y = rotationY
    ringModel.rotation.z = 0
    ringModel.updateMatrixWorld?.(true)
    cam.position.set(0, 0, activeCameraDistance)
    cam.target?.set?.(0, 0, 0)
    cam.positionUpdated?.(false)
    viewer.setDirty?.()
}

let activeCameraDistance = 6

function computeFit() {
    if (!ringModel) return
    ringModel.position.set(0, 0, 0)
    ringModel.rotation.order = 'YXZ'
    ringModel.rotation.x = 0
    ringModel.rotation.y = 0
    ringModel.rotation.z = 0
    ringModel.updateWorldMatrix?.(true, true)
    const box = computeRingBounds(ringModel)
    if (box.isEmpty()) return
    const size = box.getSize(new Vector3())
    const center = box.getCenter(new Vector3())
    ringFitCenter.x = center.x; ringFitCenter.y = center.y; ringFitCenter.z = center.z
    const maxDim = Math.max(size.x, size.y, size.z, 0.001)
    activeCameraDistance = maxDim * 1.5
}

async function setup() {
    try {
        const canvas = document.getElementById('webgi-canvas') as HTMLCanvasElement
        const container = canvas.parentElement || document.body

        // Same quality pipeline as the ring builder: EXRLoadPlugin, DiamondPlugin,
        // dual env on scene + gem, ACES tone mapping, shadow floor.
        ijewelViewer = new IjewelViewer(container, {
            modelUrl: MODEL_PATH,
            sceneConfig: { Environment: ENV_PATH },
            metal: { color: '#d4a437', metalness: 1, roughness: 0.12, envMapIntensity: 2.4 },
            diamond: { color: '#ffffff', transmission: 0.92, ior: 2.6, sparkle: 2.0 },
            plugins: {},
        })
        await ijewelViewer.init()
        viewer = ijewelViewer.getViewerApp()
        ;(window as any).__ringViewer = ijewelViewer

        await ijewelViewer.loadModel(MODEL_PATH)

        ringModel = ijewelViewer.getRingModel() || null
        if (!ringModel) throw new Error('No ring model after load')

        computeFit()
        frameRing()
        modelLoaded = true

        // Auto-rotation
        viewer.addEventListener('preFrame', () => {
            if (!modelLoaded || !ringModel) return
            if (AUTO_ROTATE) rotationY += ROTATION_SPEED * 0.005
            ringModel.rotation.y = rotationY
            ringModel.updateMatrixWorld?.(true)
            if (viewer && typeof viewer.setDirty === 'function') viewer.setDirty()
        })

        // Drag to rotate / tilt
        let dragging = false
        let lastX = 0, lastY = 0
        canvas.addEventListener('pointerdown', (e) => { dragging = true; lastX = e.clientX; lastY = e.clientY; canvas.setPointerCapture(e.pointerId) })
        canvas.addEventListener('pointermove', (e) => {
            if (!dragging || !ringModel) return
            const dx = e.clientX - lastX, dy = e.clientY - lastY
            lastX = e.clientX; lastY = e.clientY
            ringModel.rotation.y += dx * 0.008
            const tilt = ringModel.rotation.x + dy * 0.006
            ringModel.rotation.x = Math.max(-MAX_TILT, Math.min(MAX_TILT, tilt))
            viewer.setDirty?.()
        })
        const stop = () => { dragging = false }
        canvas.addEventListener('pointerup', stop)
        canvas.addEventListener('pointercancel', stop)

        loaderEl.classList.add('hidden')
        if (viewer && typeof viewer.setDirty === 'function') viewer.setDirty()
    } catch (e) {
        console.error('Bare viewer setup failed:', e)
        loaderEl.classList.add('hidden')
        const el = document.getElementById('loader') as HTMLElement
        el.textContent = 'Failed to load ring'
    }
}

setup()
